'use client';

import { useEffect, useId, useRef, useState } from 'react';
import './showreel-hero.css';

export interface ShowreelHeroProps {
  eyebrow?: string;
  title: string;
  description?: string;
  poster: string;
  posterAlt?: string;
  videoSrc: string;
  videoLabel?: string;
  captionsSrc?: string;
  transcript?: string;
  className?: string;
}

/** A cinematic poster and an explicitly opened, manually played native video. */
export function ShowreelHero({
  eyebrow,
  title,
  description,
  poster,
  posterAlt = '',
  videoSrc,
  videoLabel = 'Watch the film',
  captionsSrc,
  transcript,
  className = '',
}: ShowreelHeroProps) {
  const [expanded, setExpanded] = useState(false);
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const video = useRef<HTMLVideoElement>(null);
  const opener = useRef<HTMLButtonElement>(null);
  const instance = useId();
  const titleId = `ac-showreel-title-${instance}`;
  const dialogId = `ac-showreel-dialog-${instance}`;
  const dialogTitleId = `${dialogId}-title`;

  useEffect(() => {
    if (!expanded) return;
    const modal = dialog.current;
    const player = video.current;
    if (!modal) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    if (!modal.open) modal.showModal();
    return () => {
      player?.pause();
      try {
        if (player) player.currentTime = 0;
      } catch {
        // A source with no loaded metadata may not have a seekable timeline yet.
      }
      if (modal.open) modal.close();
      document.body.style.overflow = previousOverflow;
      opener.current?.focus({ preventScroll: true });
    };
  }, [expanded]);

  function openFilm() {
    setExpanded(true);
  }

  return (
    <section className={`ac-showreel-hero ${className}`.trim()} aria-labelledby={titleId}>
      <img className="ac-showreel-poster" src={poster} alt={posterAlt} />
      <div className="ac-showreel-shade" aria-hidden="true" />
      <div className="ac-showreel-content">
        <div className="ac-showreel-intro">
          {eyebrow && <p className="ac-showreel-eyebrow">{eyebrow}</p>}
          <h2 id={titleId}>{title}</h2>
        </div>
        <div className="ac-showreel-bottom">
          {description && <p className="ac-showreel-description">{description}</p>}
          <button
            ref={opener}
            type="button"
            className="ac-showreel-play"
            aria-haspopup="dialog"
            aria-expanded={expanded}
            aria-controls={dialogId}
            onClick={openFilm}
          >
            <span className="ac-showreel-play-icon" aria-hidden="true">
              <svg viewBox="0 0 20 20" width="20" height="20" fill="currentColor"><path d="M7 4.5v11L15.5 10z" /></svg>
            </span>
            <span>{videoLabel}</span>
            <span className="ac-showreel-play-arrow" aria-hidden="true">↗</span>
          </button>
        </div>
      </div>
      <dialog
        ref={dialog}
        id={dialogId}
        className="ac-showreel-dialog"
        aria-labelledby={dialogTitleId}
        onCancel={event => { event.preventDefault(); setExpanded(false); }}
        onClose={() => { if (!dialog.current?.open) setExpanded(false); }}
      >
        <header className="ac-showreel-dialog-header">
          <h2 id={dialogTitleId}>{videoLabel}</h2>
          <button type="button" autoFocus onClick={() => setExpanded(false)}>Close <span aria-hidden="true">×</span></button>
        </header>
        <video
          ref={video}
          className="ac-showreel-video"
          src={videoSrc}
          poster={poster}
          controls
          playsInline
          preload="none"
          aria-label={videoLabel}
          onError={() => setFailedSource(videoSrc)}
          onLoadedMetadata={() => setFailedSource(null)}
        >
          {captionsSrc && <track kind="captions" src={captionsSrc} srcLang="en" label="English captions" default />}
          Your browser cannot play this video. <a href={videoSrc}>Open the video file</a>.
        </video>
        {failedSource === videoSrc && <p className="ac-showreel-error" role="alert">This video could not be loaded. <a href={videoSrc} target="_blank" rel="noreferrer">Open the video file</a> or check the video source.</p>}
        <div className="ac-showreel-dialog-copy">
          <p className="ac-showreel-play-note">Use the player controls to start the film.</p>
          {transcript && <details className="ac-showreel-transcript"><summary>Read the transcript</summary><p>{transcript}</p></details>}
        </div>
      </dialog>
    </section>
  );
}

.ac-showreel-hero,
.ac-showreel-hero *,
.ac-showreel-dialog,
.ac-showreel-dialog * { box-sizing: border-box; }

.ac-showreel-hero {
  --ac-showreel-paper: #f5f3e9;
  --ac-showreel-ink: #172420;
  position: relative;
  isolation: isolate;
  container-type: inline-size;
  min-height: 560px;
  overflow: hidden;
  border-radius: 4px;
  background: var(--ac-showreel-ink);
  color: var(--ac-showreel-paper);
  font-family: inherit;
}

.ac-showreel-poster,
.ac-showreel-shade { position: absolute; inset: 0; width: 100%; height: 100%; }
.ac-showreel-poster { object-fit: cover; z-index: -2; }
.ac-showreel-shade { z-index: -1; background: linear-gradient(180deg, rgb(7 24 24 / 42%), rgb(7 24 24 / 5%) 45%, rgb(7 24 24 / 72%)); }
.ac-showreel-content { min-height: inherit; padding: clamp(28px, 5vw, 64px); display: flex; flex-direction: column; justify-content: space-between; gap: 80px; }
.ac-showreel-eyebrow { margin: 0 0 26px; font-size: 10px; line-height: 1.5; letter-spacing: .2em; text-transform: uppercase; }
.ac-showreel-intro h2 { max-width: 13ch; margin: 0; font-size: clamp(48px, 7.4vw, 98px); font-family: var(--serif, Georgia, serif); font-weight: 400; line-height: .99; letter-spacing: -.055em; white-space: pre-line; text-wrap: balance; }
.ac-showreel-bottom { display: flex; justify-content: space-between; align-items: end; gap: 28px; }
.ac-showreel-description { max-width: 34ch; margin: 0; font-size: 14px; line-height: 1.65; text-wrap: pretty; }
.ac-showreel-play { display: inline-flex; flex-shrink: 0; align-items: center; gap: 16px; min-height: 58px; padding: 7px 20px 7px 7px; border: 1px solid rgb(255 255 255 / 55%); border-radius: 99px; background: rgb(246 245 239 / 96%); color: var(--ac-showreel-ink); font: inherit; font-size: 12px; font-weight: 600; cursor: pointer; transition: background 180ms ease, transform 180ms ease; }
.ac-showreel-play-icon { width: 42px; height: 42px; display: grid; place-items: center; border-radius: 50%; background: var(--ac-showreel-ink); color: var(--ac-showreel-paper); }
.ac-showreel-play-arrow { margin-left: 14px; font-size: 20px; font-weight: 400; }
.ac-showreel-play:focus-visible { outline: 3px solid white; outline-offset: 5px; }
.ac-showreel-dialog { width: min(960px, calc(100vw - 32px)); max-height: calc(100dvh - 32px); margin: auto; padding: 0; overflow: auto; border: 1px solid #454b46; border-radius: 12px; background: #192420; color: #f5f3e9; font-family: inherit; overscroll-behavior: contain; }
.ac-showreel-dialog::backdrop { background: rgb(6 12 10 / 84%); }
.ac-showreel-dialog-header { padding: 12px 18px 12px 24px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.ac-showreel-dialog-header h2 { margin: 0; font-size: 14px; font-weight: 500; }
.ac-showreel-dialog-header button { min-width: 88px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 16px; border: 1px solid #556059; border-radius: 99px; background: transparent; color: inherit; font: inherit; font-size: 12px; cursor: pointer; }
.ac-showreel-dialog-header button span { font-size: 24px; font-weight: 300; }
.ac-showreel-video { display: block; width: 100%; max-height: 65dvh; aspect-ratio: 16 / 9; background: #080d0b; object-fit: contain; }
.ac-showreel-dialog-copy { padding: 16px 24px 24px; }
.ac-showreel-play-note { margin: 0; color: #bac6bd; font-size: 12px; line-height: 1.6; }
.ac-showreel-transcript { margin-top: 16px; padding-top: 16px; border-top: 1px solid #46534b; }
.ac-showreel-transcript summary { width: fit-content; min-height: 44px; align-content: center; cursor: pointer; font-size: 13px; }
.ac-showreel-transcript p { max-width: 70ch; margin: 6px 0 0; font-size: 13px; line-height: 1.75; white-space: pre-line; }
.ac-showreel-error { margin: 18px 24px 0; padding: 14px; border: 1px solid #b58969; border-radius: 6px; color: #f3d4bd; font-size: 13px; line-height: 1.7; }
.ac-showreel-error a { color: inherit; text-underline-offset: 3px; }
.ac-showreel-dialog :is(button, summary, a):focus-visible { outline: 2px solid #e9c39d; outline-offset: 4px; }

@media (hover: hover) and (pointer: fine) {
  .ac-showreel-play:hover { background: #fff; transform: translateY(-3px); }
  .ac-showreel-dialog-header button:hover { background: #35463b; }
}

@container (max-width: 600px) {
  .ac-showreel-content { padding: 28px; gap: 64px; }
  .ac-showreel-intro h2 { font-size: clamp(46px, 12cqi, 72px); }
  .ac-showreel-bottom { flex-direction: column; align-items: start; gap: 24px; }
  .ac-showreel-description { font-size: 13px; }
  .ac-showreel-play { min-height: 54px; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-showreel-play { transition: none; }
  .ac-showreel-play:hover { transform: none; }
}


/* The photographic hero keeps white overlay copy; dialog chrome follows the page. */
:where([data-theme="light"]) .ac-showreel-dialog { --ac-showreel-dialog-surface: #fafbf8; --ac-showreel-dialog-ink: #202722; --ac-showreel-dialog-muted: #687269; --ac-showreel-dialog-line: #d7ded4; color-scheme: light; }
:where([data-theme="dark"], .dark) .ac-showreel-dialog { --ac-showreel-dialog-surface: #191e1b; --ac-showreel-dialog-ink: #edf2eb; --ac-showreel-dialog-muted: #a7b3a3; --ac-showreel-dialog-line: #3d483e; color-scheme: dark; }
.ac-showreel-dialog { background: var(--ac-showreel-dialog-surface, #192420); color: var(--ac-showreel-dialog-ink, #f5f3e9); border-color: var(--ac-showreel-dialog-line, #454b46); }
.ac-showreel-dialog-header button, .ac-showreel-transcript { border-color: var(--ac-showreel-dialog-line, #46534b); }
.ac-showreel-play-note { color: var(--ac-showreel-dialog-muted, #bac6bd); }
@media (hover: hover) and (pointer: fine) { .ac-showreel-dialog-header button:hover { background: color-mix(in srgb, var(--ac-showreel-dialog-ink, #f5f3e9) 10%, transparent); } }
